CREATE TABLE IF NOT EXISTS kv (key TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS meta (id INTEGER PRIMARY KEY CHECK (id = 1), version INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS live_events (id INTEGER PRIMARY KEY AUTOINCREMENT, room_id TEXT NOT NULL, type TEXT NOT NULL, data TEXT NOT NULL, ts INTEGER NOT NULL);
CREATE INDEX IF NOT EXISTS live_events_room ON live_events(room_id, id);
CREATE TABLE IF NOT EXISTS live_media (room_id TEXT NOT NULL, seq INTEGER NOT NULL, chunk TEXT, frame TEXT, mime TEXT, ts INTEGER NOT NULL, PRIMARY KEY (room_id, seq));
CREATE TABLE IF NOT EXISTS live_viewers (room_id TEXT NOT NULL, client_id TEXT NOT NULL, user_id TEXT, last_seen INTEGER NOT NULL, PRIMARY KEY (room_id, client_id));
CREATE TABLE IF NOT EXISTS live_counters (room_id TEXT PRIMARY KEY, likes INTEGER NOT NULL DEFAULT 0, comments INTEGER NOT NULL DEFAULT 0, peak INTEGER NOT NULL DEFAULT 0, seq INTEGER NOT NULL DEFAULT 0, mime TEXT);
